package main

import (
    "context"
    "database/sql"
)

func transfer(ctx context.Context, db *sql.DB, from, to string, amount int) error {
    // Открой транзакцию, выполни оба изменения и подтверди её.
    _, err := db.ExecContext(ctx, "UPDATE accounts SET balance = balance - $1 WHERE id = $2", amount, from)
    if err != nil {
        return err
    }
    _, err = db.ExecContext(ctx, "UPDATE accounts SET balance = balance + $1 WHERE id = $2", amount, to)
    return err
}

func main() {}

